SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE (EXISTS  (SELECT  1  FROM "public"."article" AS "__be_0_article" WHERE (((("__be_0_article"."author_id") = ("public"."author"."id")) AND ('true')) AND ((((("__be_0_article"."author_id") = (('1')::integer)) AND ('true')) AND ('true')) AND ((EXISTS  (SELECT  1  FROM "public"."comment" AS "__be_1_comment" WHERE (((("__be_1_comment"."article_id") = ("__be_0_article"."id")) AND ('true')) AND (((EXISTS  (SELECT  1  FROM "public"."article" AS "__be_2_article" WHERE (((("__be_2_article"."id") = ("__be_1_comment"."article_id")) AND ('true')) AND (('true') AND (((("__be_2_article"."author_id") = (('1')::integer)) AND ('true')) AND ('true'))))     )) AND ('true')) AND (((("__be_1_comment"."id") = (('8')::integer)) AND ('true')) AND ('true'))))     )) AND ('true'))))     ))   ORDER BY "id" ASC NULLS LAST  ) AS "_root.base"    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"
